// 버전6(수채화) 나무 데이터 — 사용자가 보내준 수채화풍 벌거벗은 나무 사진을 격자로
// 스캔해 실제 가지 픽셀만 앵커로 씀(몸통·뿌리 제외), 잎마다 줄기 위치/각도를 감지해
// 가지 각도에 맞춰 회전. v2~v5와 완전히 분리된 파일이라 이 파일을 고쳐도 다른 버전에는
// 영향 없음.

function seededRandom(seed) {
  let s = seed | 0;
  return function () {
    s = (s + 0x6d2b79f5) | 0;
    let t = Math.imul(s ^ (s >>> 15), 1 | s);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

function shuffledAnchors(list) {
  const arr = [...list];
  const rand = seededRandom(20260923);
  for (let i = arr.length - 1; i > 0; i--) {
    const j = Math.floor(rand() * (i + 1));
    [arr[i], arr[j]] = [arr[j], arr[i]];
  }
  return arr;
}

// tree-bare-watercolor.png 원본 픽셀 크기와, 그 사진을 SVG 로컬 좌표(GROUND_ANCHOR=(120,232)
// 기준)에 배치하는 스케일/오프셋. 트렁크 밑동 픽셀(657,1250)을 GROUND_ANCHOR에 맞춤.
const TREE_PHOTO_W = 1223;
const TREE_PHOTO_H = 1286;
const TREE_PHOTO_SCALE = 0.179;
const TREE_PHOTO_OFFSET_X = 120 - 657 * TREE_PHOTO_SCALE;
const TREE_PHOTO_OFFSET_Y = 232 - 1250 * TREE_PHOTO_SCALE;

export const TREE_V6_IMAGE = {
  src: '/images/v6-watercolor/tree-bare-watercolor.png',
  x: TREE_PHOTO_OFFSET_X,
  y: TREE_PHOTO_OFFSET_Y,
  width: TREE_PHOTO_W * TREE_PHOTO_SCALE,
  height: TREE_PHOTO_H * TREE_PHOTO_SCALE,
};

function photoToSvg(px, py) {
  return { x: TREE_PHOTO_OFFSET_X + px * TREE_PHOTO_SCALE, y: TREE_PHOTO_OFFSET_Y + py * TREE_PHOTO_SCALE };
}

