export function getLeafV6(index) {
  const anchor = LEAF_ANCHORS_V6[index % LEAF_ANCHORS_V6.length];
  const ring = Math.floor(index / LEAF_ANCHORS_V6.length);
  const rand = seededRandom(index * 2654435761 + 9);
  const anchorAngleRad = (anchor.angle * Math.PI) / 180;
  let jitterAngle;
  let radius;
  if (ring === 0) {
    jitterAngle = rand() * Math.PI * 2;
    radius = 0.8 + rand() * 0.8;
  } else {
    jitterAngle = anchorAngleRad + (rand() - 0.5) * Math.PI * 0.9;
    radius = 1 + Math.min(ring * 0.3, 4) + rand() * 0.9;
  }
  const variant = LEAF_IMAGES_V6[index % LEAF_IMAGES_V6.length];
  const jitterRot = (rand() - 0.5) * 50;
  // 대부분은 가지 바깥쪽을 향하되, 일부(대략 5개 중 1개)는 180도 뒤집어서 아래로 처진
  // (드루핑) 잎도 섞이게 함 — 실제 나무도 잎이 전부 바깥쪽만 향하지 않고 중력에 눌려
  // 안쪽/아래로 처진 잎이 섞여 있음
  const droop = rand() < 0.22 ? 180 : 0;
  const rot = anchor.angle + 90 - (variant.stemAngle * 180) / Math.PI + jitterRot + droop;
  // 원본 잎 시트의 23장이 전부 "줄기 아래, 잎몸이 같은 쪽으로 살짝 휜" 거의 같은 포즈로
  // 그려져 있어서, 회전만으로는 이 휜 방향(손잡이 방향) 자체는 절대 안 바뀜 — 그래서
  // 회전을 아무리 다양하게 줘도 나무 전체가 한쪽으로 쓸린 것처럼 보였음. 절반 정도를
  // 좌우로 뒤집어서(scale(-1,1)) 그 휜 방향도 섞이게 함
  const flip = rand() < 0.5;
  return {
    x: anchor.x + Math.cos(jitterAngle) * radius,
    y: anchor.y + Math.sin(jitterAngle) * radius * 0.85,
    rot,
    flip,
    scale: 0.55 + rand() * 0.3,
    variant,
    behind: anchor.behind,
  };
}

// 포도송이 열매 자리 — 앵커끼리 가까이 몰리면 포도송이 이미지가 겹쳐서 뭉친 덩어리처럼
// 보이는 문제(마인크래프트 버전에서 먼저 겪음)가 있어서, 처음부터 최소 거리 필터로
// 서로 떨어진 자리만 고름
function minDistanceFilter(anchors, minDist, maxCount) {
  const picked = [];
  for (const a of anchors) {
    if (picked.every((p) => Math.hypot(p.x - a.x, p.y - a.y) >= minDist)) {
      picked.push(a);
      if (picked.length >= maxCount) break;
    }
  }
  return picked;
}
export const FRUIT_SPOTS_V6 = minDistanceFilter(
  shuffledAnchors(LEAF_ANCHORS_V6),
  9,
  Math.floor(LEAF_ANCHORS_V6.length / 6)
).map((a) => ({ x: a.x, y: a.y, behind: a.behind }));
